import {exams,selectableExams,verifiedAt,scheduleUrl} from './exams.js';
import {product,tracks,parts,officialSources} from './product.js';
import {KEY,REVIEW_SUCCESSES_REQUIRED,dateKey,addDays,daysUntil,initial,validate,playable,firstAttempts,percent,submitAnswer,randomSample} from './core.js';
import {ApiClient,AccountOutbox,safeReturnRoute,applyCloudAttempt,applySyncEvent,errorMessage} from './cloud.js';

const main=document.querySelector('main');
const dialog=document.querySelector('dialog');
const notice=document.querySelector('#notice');
const esc=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const letter=index=>String.fromCharCode(65+index);
const number=value=>new Intl.NumberFormat('zh-HK').format(value);
const fmtDate=day=>new Intl.DateTimeFormat('zh-HK',{year:'numeric',month:'long',day:'numeric'}).format(new Date(day+'T00:00:00+08:00'));
const partMeta=id=>parts.find(part=>part.id===id)||{id,title:'綜合課題',short:'綜合'};
const displayPart=id=>track().id==='sqe'&&id===7?6:id;

let state=initial();
let questions=[];
let storageProblem='';
let questionLoadError='';
let noticeTimeout;
let lastAction=Date.now();
let lastTick=Date.now();
let busy=false;
const api=new ApiClient();
const outbox=new AccountOutbox({api});
let account=null,configuration={authEnabled:false,termsVersion:'',privacyVersion:'',passwordMinLength:12},guestQuestions=[],cloudCursor=0,cloudBusy=false,authBusy=false,authNotice='',authError='',returnTo='account';
let settingsVersion=0,syncError='',cloudSession=null,cloudQuestionMap=new Map(),usageSegments=[],accountEpoch=0;
let conceptCache=new Map();
const deviceId=(()=>{try{let id=sessionStorage.getItem('propexam-device');if(!id){id=crypto.randomUUID();sessionStorage.setItem('propexam-device',id);}return id;}catch{return crypto.randomUUID();}})();
const draftKey=id=>`propexam-cloud-v1:${id}:draft`;
let initialCallback=null;
if(location.hash.startsWith('#auth-callback?')){const params=new URLSearchParams(location.hash.split('?')[1]||'');initialCallback={tokenHash:params.get('token_hash'),type:params.get('type')};window.history.replaceState(null,'',location.pathname+location.search+'#login');}
const recordScope=()=>account?'此帳戶的雲端學習紀錄':'此瀏覽器的訪客紀錄';
const syncLabel=()=>!account?'訪客模式':outbox.running||cloudBusy?'同步中':outbox.paused?'登入已失效':outbox.lastError||syncError?'同步失敗，請重試':outbox.pending?`${outbox.pending} 筆待同步`:'已同步';

// 清除舊私人原型及測試版本的本機資料；公開版本只使用新版的獨立儲存空間。
try{localStorage.removeItem('eaqe-prototype-v1');localStorage.removeItem('propexam-hk-v2')}catch{}

function read(){if(account)return structuredClone(state);try{const raw=localStorage.getItem(KEY);return raw?validate(JSON.parse(raw)):initial()}catch{storageProblem='學習紀錄未能讀取。';return initial()}}
state=read();
function toast(message,persistent=false){clearTimeout(noticeTimeout);notice.textContent=message;if(!persistent)noticeTimeout=setTimeout(()=>notice.textContent='',4000)}
async function mutate(fn,redraw=true){const operation=()=>{if(storageProblem){toast(storageProblem,true);return false}const next=structuredClone(read());try{fn(next);if(!account)localStorage.setItem(KEY,JSON.stringify(next));state=next;if(account)saveDraft();if(redraw)render();return true}catch(error){toast(error.name==='QuotaExceededError'?'儲存空間不足，請先匯出紀錄。':errorMessage(error),true);return false}};return navigator.locks?navigator.locks.request(account?`propexam-${account.user.id}`:KEY,operation):operation()}
const route=()=>location.hash.slice(1)||'home';
function go(hash){if(route()===hash){render();main.focus()}else location.hash=hash}
const track=()=>tracks[state.settings.track]||tracks.eaqe;
const trackQuestions=()=>questions.filter(question=>(question.examTracks||['eaqe']).includes(track().id));
const paidActive=()=>account?.entitlement?.plan==='paid'&&account.entitlement.expiresAt&&Date.parse(account.entitlement.expiresAt)>Date.now();
const unlocked=question=>paidActive()||question.free===true;
const attempts=()=>{if(account)return state.attempts;const ids=new Set(questions.map(question=>question.id));return state.attempts.filter(attempt=>ids.has(attempt.questionId))};
const reviews=()=>{if(account)return Object.entries(state.reviews).filter(([,review])=>review.status!=='completed');const ids=new Set(questions.map(question=>question.id));return Object.entries(state.reviews).filter(([id])=>ids.has(id))};
const trackAttempts=()=>{if(account)return attempts().filter(attempt=>track().parts.includes(attempt.part));const ids=new Set(trackQuestions().map(question=>question.id));return attempts().filter(attempt=>ids.has(attempt.questionId))};
const due=()=>{if(account)return reviews().filter(([id,review])=>review.due<=dateKey()&&trackAttempts().some(a=>a.questionId===id));const ids=new Set(trackQuestions().map(question=>question.id));return reviews().filter(([id,review])=>ids.has(id)&&review.due<=dateKey())};
const answeredIds=()=>new Set(attempts().map(attempt=>attempt.questionId));
const attemptsFor=id=>attempts().filter(attempt=>attempt.questionId===id).sort((a,b)=>a.at-b.at);
const current=()=>questions.find(question=>question.id===state.session?.ids[state.session.index]);
function saveDraft(){if(!account)return;const session=state.session;localStorage.setItem(draftKey(account.user.id),JSON.stringify(session?{sessionId:session.id,index:session.index,draft:session.draft,pendingEventId:session.pendingEventId||null}:null));}
function syncBanner(){return `<div class="sync-strip" role="status"><span class="sync-dot ${outbox.lastError||syncError||outbox.paused?'error':''}" aria-hidden="true"></span><span data-sync-status>${esc(syncLabel())}</span>${account?outbox.paused?'<a class="text-link" href="#login">重新登入</a>':`<button class="quiet" data-action="sync-now" ${cloudBusy?'disabled':''}>重新整理</button>`:'<a class="text-link" href="#login">登入以同步</a>'}</div>`;}
function mergeSession(session){cloudSession=session;const items=session.items||[];for(const item of items){const question={...item,options:item.options.map(o=>o.text),optionIds:item.options.map(o=>o.id),free:!!item.isFree,examTracks:item.tracks||[session.track],concept:item.concept||partMeta(item.part).short};cloudQuestionMap.set(item.id,question);}questions=Array.from(cloudQuestionMap.values());const previous=state.session;state.session=session.status==='completed'?null:{id:session.id,title:session.mode==='review'?'錯題重溫':'雲端練習',mode:session.mode,track:session.track,ids:items.map(q=>q.id),index:session.index||0,result:null,draft:{},activeMs:0,serverVersion:session.version};if(previous?.id===session.id&&previous.index===state.session?.index){state.session.draft=previous.draft||{};state.session.activeMs=previous.activeMs||0;state.session.pendingEventId=previous.pendingEventId;}
 if(state.session&&session.result){state.session.result=applyCloudAttempt(state,{attempt:session.result,...(Object.hasOwn(session,'review')?{review:session.review}:{})},session);state.session.explanation=session.explanation;}
 if(state.session){try{const draft=JSON.parse(localStorage.getItem(draftKey(account.user.id))||'null');if(draft?.sessionId===session.id&&draft.index===state.session.index&&!state.session.result){state.session.draft=draft.draft||{};state.session.pendingEventId=draft.pendingEventId;}}catch{}}
}
function setAccount(value){outbox.activate(value.user.id);accountEpoch++;cloudBusy=false;account=value;api.expectedAccountId=value.user.id;settingsVersion=value.settingsVersion||0;state=initial();state.settings={...state.settings,...value.settings};questions=[];cloudQuestionMap=new Map();conceptCache.clear();cloudSession=null;cloudCursor=0;syncError='';storageProblem='';usageSegments=[];lastTick=Date.now();}
function setGuest(){accountEpoch++;cloudBusy=false;const oldId=account?.user.id;outbox.deactivate();api.expectedAccountId=null;account=null;cloudSession=null;cloudQuestionMap=new Map();conceptCache.clear();questions=guestQuestions;cloudCursor=0;settingsVersion=0;syncError='';storageProblem='';usageSegments=[];state=read();if(oldId)try{localStorage.removeItem(draftKey(oldId));}catch{}}
async function acknowledge(event,response){if(event.kind==='attempt'){const attempt=applyCloudAttempt(state,response,cloudSession);const question=cloudQuestionMap.get(attempt.questionId);if(question&&response.explanation){const content=response.explanation.content;question.explanation=typeof content==='string'?content:content?.core||content?.explanation||content?.content||content?.summary||'';question.concept=content?.concept||attempt.concept||question.concept;question.optionNotes=content?.options?question.optionIds.map(id=>content.options[id]):content?.optionNotes;attempt.concept=question.concept;}if(state.session?.id===event.payload.sessionId&&state.session.ids[state.session.index]===attempt.questionId){state.session.result=attempt;state.session.explanation=response.explanation;state.session.serverVersion=response.sessionVersion;state.session.pendingEventId=null;state.session.draft={};}saveDraft();}
 if(event.kind==='review'){const attempt=state.attempts.find(a=>a.id===event.payload.attemptId);if(attempt){attempt.postUncertain=true;if(response.review)state.reviews[attempt.questionId]=response.review;if(state.session?.result?.id===attempt.id)state.session.result.postUncertain=true;}}
 if(['attempt','review'].includes(event.kind)){conceptCache.clear();await loadReviewConcepts();}
}
async function flushOutbox(manual=false){if(!account)return;await outbox.flushLocked({manual,onAck:async(event,response)=>{await acknowledge(event,response);if(event.kind!=='usage'&&!authBusy)render();},onChange:()=>{const label=document.querySelector('[data-sync-status]');if(label)label.textContent=syncLabel();}});if(outbox.paused){if(!['login','signup','forgot','reset'].includes(route()))render();toast('登入已失效。待同步資料已保留，請重新登入。',true);}}
async function syncCloud({refreshAccount=false,manual=false}={}){if(!account||cloudBusy)return;const epoch=accountEpoch;cloudBusy=true;syncError='';render();try{if(refreshAccount){const value=await api.request('/api/account');if(epoch!==accountEpoch)return;if(value.user.id!==account.user.id){setAccount(value);toast('帳戶已在另一分頁切換。原帳戶待同步資料已保留。',true);await syncCloud();return;}account=value;api.expectedAccountId=value.user.id;settingsVersion=value.settingsVersion||0;}await flushOutbox(manual);if(epoch!==accountEpoch)return;let pages=0,more=true;while(more&&pages++<100){const data=await api.request(`/api/sync?cursor=${cloudCursor}&limit=100`);if(epoch!==accountEpoch)return;for(const event of data.events||[])applySyncEvent(state,event);cloudCursor=data.cursor??cloudCursor;more=!!data.hasMore;if(data.settings){state.settings={...state.settings,...data.settings};settingsVersion=data.settingsVersion??settingsVersion;}if(data.activeSessionId)account.activeSessionId=data.activeSessionId;if(data.dailyUsage){state.usage=Object.fromEntries(Object.entries(data.dailyUsage).map(([day,totals])=>[day,totals.effectiveSeconds||0]));state.foregroundUsage=Object.fromEntries(Object.entries(data.dailyUsage).map(([day,totals])=>[day,totals.foregroundSeconds||0]));}}if(more)syncError='紀錄較多，請再按重新整理繼續同步。';if(state.cloudSession)mergeSession(state.cloudSession);if(account.activeSessionId){const data=await api.request(`/api/practice-sessions?id=${encodeURIComponent(account.activeSessionId)}`);if(epoch!==accountEpoch)return;if(data.session)mergeSession(data.session);}await loadReviewConcepts({force:true});}catch(error){if(epoch===accountEpoch){syncError=errorMessage(error);if(error.status===401)outbox.paused=true;}}finally{if(epoch===accountEpoch){cloudBusy=false;render();}}}
async function loadAccount(){try{const value=await api.request('/api/account');if(account?.user.id===value.user.id){account=value;}else setAccount(value);await syncCloud();}catch(error){if(error.status===401&&account)setGuest();if(![401,503,404].includes(error.status))syncError=errorMessage(error);}finally{render();}}
function statsHTML(items){return `<div class="stats">${items.map(([value,label])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div>`}
function trackSwitch(){return `<div class="track-switch" role="group" aria-label="選擇考試"><button data-action="set-track" data-track="eaqe" class="${track().id==='eaqe'?'active':''}"><strong>大牌</strong><span>EAQE</span></button><button data-action="set-track" data-track="sqe" class="${track().id==='sqe'?'active':''}"><strong>細牌</strong><span>SQE</span></button></div>`}
function examSelect(trackId=track().id,selectedDate=state.settings.examDate){const available=selectableExams(dateKey(),selectedDate,trackId);return `<label class="field">目標場次<select name="examDate"><option value="">稍後決定</option>${available.map(exam=>`<option value="${exam.date}" ${exam.date===selectedDate?'selected':''}>${fmtDate(exam.date)} · ${exam.time}</option>`).join('')}</select></label>`}
function nextPool(){const pool=trackQuestions().filter(unlocked);const answered=answeredIds();const pending=pool.filter(question=>!answered.has(question.id));if(pending.length)return pending.slice(0,10);const dueIds=new Set(due().map(([id])=>id));const duePool=pool.filter(question=>dueIds.has(question.id));return duePool.length?duePool.slice(0,10):pool.slice(0,10)}
const catalog=()=>account?.catalog?.filter(row=>row.track===track().id)||[];
const catalogTotal=()=>account?catalog().reduce((sum,row)=>sum+row.total,0):trackQuestions().length;
const freeCount=()=>account?catalog().reduce((sum,row)=>sum+(row.free||0),0):trackQuestions().filter(question=>question.free).length;
function cloudPractice(){const rows=catalog(),available=rows.reduce((sum,row)=>sum+row.available,0),first=firstAttempts({attempts:trackAttempts()});return `<div class="page-heading"><div><p class="eyebrow">${track().short} · ${track().code}</p><h1>練習題庫</h1><p class="muted">伺服器確認的可用題目</p></div><div class="page-actions"><a class="secondary" href="#history">錯題與紀錄</a><a class="secondary" href="#concepts">弱項概念</a>${state.session&&current()?'<a class="primary" href="#quiz">繼續練習</a>':''}</div></div>${available?`<section class="practice-overview"><div><span class="eyebrow">已覆核題庫</span><p class="library-total">${number(catalogTotal())}<small> 題</small></p><p class="muted">目前可做 ${available} 題</p></div><button class="primary" data-action="start-next">開始 10 題 →</button></section>`:'<section class="empty"><h2>雲端題庫尚未備妥</h2><p>題目須完成答案及來源覆核後才提供帳戶練習。</p><button class="secondary" data-action="sync-now">重新整理</button></section>'}${due().length?`<section class="due-strip"><strong>${due().length} 題已到重溫日期</strong><button class="secondary" data-action="review-due">立即重溫</button></section>`:''}<div class="set-list">${parts.filter(part=>track().parts.includes(part.id)).map(part=>{const row=rows.find(row=>row.part===part.id),completed=first.filter(a=>a.part===part.id).length;return `<div class="chapter-row"><span class="chapter-number">${String(displayPart(part.id)).padStart(2,'0')}</span><div><div class="chapter-title">${esc(part.title)}</div><div class="chapter-meta">${row?`${row.total} 題 · 已完成 ${completed} 題`:'待備妥'}</div></div>${row?.available?`<button class="quiet" data-action="start-part" data-part="${part.id}">開始 →</button>`:row?.total?'<a class="locked-link" href="#pricing">查看方案 ◇</a>':'<span class="muted">待備妥</span>'}</div>`}).join('')}</div>`;}
function cloudLearning(){return `<div class="page-heading"><div><p class="eyebrow">${track().short} · ${track().code}</p><h1>學習範圍</h1><p class="muted">由相關練習開始，作答後查看概念解說</p></div>${trackSwitch()}</div><div class="syllabus-list">${parts.filter(part=>track().parts.includes(part.id)).map(part=>{const row=catalog().find(row=>row.part===part.id);return `<div class="chapter-row"><span class="chapter-number">${String(displayPart(part.id)).padStart(2,'0')}</span><div><div class="chapter-title">${esc(part.title)}</div><div class="chapter-meta">${row?`已備妥 ${row.total} 題`:'教材及題目待備妥'}</div></div>${row?.available?`<button class="quiet" data-action="start-part" data-part="${part.id}">學習 →</button>`:'<span class="muted">待備妥</span>'}</div>`}).join('')}</div>`;}

function home(){const pool=trackQuestions();const free=pool.filter(question=>question.free);const session=state.session&&current()?state.session:null;const exam=exams.find(item=>item.date===state.settings.examDate&&item.track===track().id&&item.date>=dateKey());const day=exam?daysUntil(exam.date):null;const today=attempts().filter(attempt=>attempt.day===dateKey());
 return `<section class="public-hero"><div><p class="eyebrow">${product.tagline}</p><h1>先做題，<br>再真正理解答案。</h1><p class="hero-copy">練習題、逐題解說、錯題重溫及進度分析，集中處理香港地產牌照考試的取分重點。</p>${trackSwitch()}<div class="hero-actions"><button class="primary" data-action="home-start">${session?'繼續練習':'免費開始'} <span>→</span></button><a class="secondary" href="#pricing">查看試行方案</a></div><p class="microcopy">${freeCount()} 題免費試做 · 無需付款資料</p></div><aside class="exam-panel public"><span class="eyebrow">${track().short} · ${track().code}</span><h2>${track().name}</h2><div class="countdown public-count">${day===null?'—':Math.max(0,day)}<span>日</span></div><p>${exam?fmtDate(exam.date):'尚未選擇考試場次'}</p><form id="onboarding" class="exam-choice">${examSelect()}<button class="secondary" type="submit">儲存</button></form></aside></section>
 <section class="product-proof">${statsHTML([[number(account?catalogTotal():pool.length),'練習題'],[account?catalog().reduce((sum,row)=>sum+row.free,0):free.length,'免費題目'],[track().duration,'考試時間']])}</section>
 <section class="how-it-works"><div class="section-heading"><p class="eyebrow">使用方式</p><h2>每次練習都完成一個學習循環</h2></div><ol><li><span>01</span><div><h3>選擇考試</h3><p>切換大牌或細牌，只顯示相關範圍。</p></div></li><li><span>02</span><div><h3>按綱要練習</h3><p>完成題目後立即查看答案及概念。</p></div></li><li><span>03</span><div><h3>集中處理錯題</h3><p>答錯或不確定的題目自動加入重溫。</p></div></li><li><span>04</span><div><h3>查看進步</h3><p>按綱要分析正確率、覆蓋及使用時間。</p></div></li></ol></section>
 <section class="exam-comparison"><div class="section-heading"><p class="eyebrow">大牌與細牌</p><h2>重疊範圍共用，專屬內容清楚分開</h2></div><div class="comparison-grid"><div><h3>共同範圍</h3><p>六個核心知識範圍</p><p class="muted">行業、條例、相關法例、查冊、樓宇知識及租務。</p></div><div><h3>大牌專屬</h3><p>估價及業務管理</p><p class="muted">EAQE 第 6 及第 8 部分。</p></div><div><h3>考試形式</h3><p>${track().format}</p><p class="muted">${track().pass}</p></div></div><p class="source-note">資料依據地產代理監管局考試資料，核實日期：${officialSources.verifiedAt}。<a class="text-link" href="${officialSources.exam}" target="_blank" rel="noopener noreferrer">查看官方資料 ↗</a></p></section>
 ${today.length?`<section class="return-strip"><div><strong>今日已完成 ${today.length} 題</strong><span>${esc(recordScope())}。</span></div><a class="secondary" href="#analysis">查看進度</a></section>`:''}`}

function learning(){if(account)return cloudLearning();const pool=trackQuestions();return `<div class="page-heading"><div><p class="eyebrow">${track().short} · ${track().code}</p><h1>學習範圍</h1><p class="muted">由概念重點直接進入相關練習</p></div>${trackSwitch()}</div><div class="syllabus-list">${parts.filter(part=>track().parts.includes(part.id)).map(part=>{const list=pool.filter(question=>question.part===part.id);const locked=!paidActive()&&!list.some(question=>question.free);const concepts=new Set(list.map(question=>question.concept)).size;return `<div class="chapter-row"><span class="chapter-number">${String(displayPart(part.id)).padStart(2,'0')}</span><div><div class="chapter-title">${esc(part.title)}</div><div class="chapter-meta">${list.length} 題 · ${concepts} 個概念${part.eaqeOnly?' · 大牌專屬':''}</div></div><a class="${locked?'locked-link':'quiet'}" href="${locked?'#pricing':`#part/${part.id}`}">${locked?'解鎖':'學習'} <span aria-hidden="true">${locked?'◇':'→'}</span></a></div>`}).join('')}</div>`}

function partPage(){const id=Number(route().split('/')[1]);const part=partMeta(id);const list=trackQuestions().filter(question=>question.part===id);if(!track().parts.includes(id))return '<div class="empty"><h1>此範圍不屬於目前考試</h1><a class="secondary" href="#learning">返回學習</a></div>';if(!paidActive()&&!list.some(question=>question.free))return paywall(part.title);const visible=list.filter(unlocked);const unique=[];const seen=new Set();for(const question of visible){if(seen.has(question.concept))continue;seen.add(question.concept);unique.push(question)}return `<article class="concept-review"><a class="quiet back-link" href="#learning">← 返回學習範圍</a><p class="eyebrow">第 ${displayPart(id)} 部分</p><h1>${esc(part.title)}</h1><p class="muted">${unique.length} 個概念重點 · 每項均可直接練習</p>${unique.map(question=>`<section class="concept-note"><h2>${esc(question.concept)}</h2><p>${esc(question.explanation)}</p><button class="quiet" data-action="review-one" data-id="${esc(question.id)}">練習這個概念 →</button></section>`).join('')}</article>`}

function practice(){if(account)return cloudPractice();const pool=trackQuestions();const unlockedPool=pool.filter(unlocked);const first=firstAttempts({attempts:attempts()});return `<div class="page-heading"><div><p class="eyebrow">${track().short} · ${track().code}</p><h1>練習題庫</h1><p class="muted">按官方綱要分類的練習題</p></div><div class="page-actions"><a class="secondary" href="#history">錯題與紀錄</a><a class="secondary" href="#concepts">弱項概念</a>${state.session&&current()&&unlocked(current())?'<a class="primary" href="#quiz">繼續練習</a>':''}</div></div><section class="practice-overview"><div><span class="eyebrow">目前題庫</span><p class="library-total">${number(pool.length)}<small> 題</small></p><p class="muted">免費可做 ${unlockedPool.length} 題 · ${paidActive()?'考期通行證已啟用':'完整題庫需使用通行證'}</p></div><button class="primary" data-action="start-next">開始 10 題 <span>→</span></button></section>${due().length?`<section class="due-strip"><div><strong>${due().length} 題已到重溫日期</strong><span>${esc(recordScope())}</span></div><button class="secondary" data-action="review-due">立即重溫</button></section>`:''}<div class="set-list">${parts.filter(part=>track().parts.includes(part.id)).map(part=>{const list=pool.filter(question=>question.part===part.id);const accessible=list.filter(unlocked);const completed=new Set(first.filter(attempt=>list.some(question=>question.id===attempt.questionId)).map(attempt=>attempt.questionId)).size;return `<div class="chapter-row"><span class="chapter-number">${String(displayPart(part.id)).padStart(2,'0')}</span><div><div class="chapter-title">${esc(part.title)}</div><div class="chapter-meta">${list.length} 題 · 已完成 ${completed} 題${part.eaqeOnly?' · 大牌專屬':''}</div><div class="bar compact"><span style="width:${list.length?completed/list.length*100:0}%"></span></div></div>${accessible.length?`<button class="quiet" data-action="start-part" data-part="${part.id}">開始 →</button>`:'<a class="locked-link" href="#pricing">解鎖 ◇</a>'}</div>`}).join('')}</div>`}

function paywall(title='完整內容'){return `<section class="paywall"><span class="lock-shape">◇</span><p class="eyebrow">考期通行證</p><h1>解鎖${esc(title)}</h1><p>首批試行價為 HK$${product.price}／每場考期。所選場次考前 ${product.preExamDays} 日開放，考試結束後 ${product.postExamDays} 日到期；重考須另購下一場。付款尚未開放，現階段無法購買或解鎖。</p><a class="primary" href="#pricing">查看方案 →</a></section>`}
function pricing(){return `<section class="pricing-hero"><p class="eyebrow">首批用戶試行方案</p><h1>按考期安排備試與考後重溫</h1><p>HK$${product.price}／每場考期。考前 ${product.preExamDays} 日開始使用，考試結束後 ${product.postExamDays} 日到期；未合格後報考下一場須重新購買。目前可免費試做 ${freeCount()} 題；付款尚未開放。</p></section><div class="pricing-grid"><section class="plan free"><p class="eyebrow">免費體驗</p><h2>HK$0</h2><ul><li>${freeCount()} 題免費試做</li><li>逐題答案及解說</li><li>個人錯題紀錄</li><li>手機及電腦瀏覽</li></ul><button class="secondary" data-action="home-start">立即試做</button></section><section class="plan paid"><span class="plan-badge">首批試行</span><p class="eyebrow">考期通行證</p><h2>HK$${product.price}<small> / 每場</small></h2><ul><li>選定一場官方考試</li><li>考前 ${product.preExamDays} 日開放，考後 ${product.postExamDays} 日到期</li><li>備試題目、概念解說及弱項重溫</li><li>跨章練習及進度分析</li><li>未合格後報考下一場須重新購買；不自動續訂</li></ul><button class="primary" data-action="buy">查看試行方案 →</button><p class="microcopy">方案範圍待確認；付款尚未開放，目前不會收取款項。</p></section></div><section class="pricing-note"><h2>成績公布時間</h2><p>官方紙本考試成績一般於考後第 14 個工作天公布，可能晚於通行證到期。通行證期限按考期計算，不延至成績公布日。<a class="text-link" href="https://www.eaa.org.hk/zh-hk/Examination/Qualifying-examinations-results" target="_blank" rel="noopener noreferrer">查看監管局公布 ↗</a></p></section>`}

function history(){const completed=account?Array.from(new Set(trackAttempts().map(a=>a.questionId))).map(id=>questions.find(q=>q.id===id)||{id,part:attemptsFor(id).at(-1)?.part,concept:attemptsFor(id).at(-1)?.concept||'已作答題目'}):trackQuestions().filter(unlocked).filter(question=>attemptsFor(question.id).length);const pendingIds=new Set(reviews().map(([id])=>id));const pending=completed.filter(question=>pendingIds.has(question.id));const reviewed=completed.filter(question=>attemptsFor(question.id).length>1);const rows=list=>list.length?list.map(question=>{const records=attemptsFor(question.id);const last=records.at(-1);const review=state.reviews[question.id];const reviewState=review?review.status==='completed'?' · 完成重溫':review.status==='consolidate'?` · 鞏固進度 ${Math.min(review.successes||0,REVIEW_SUCCESSES_REQUIRED)} / ${REVIEW_SUCCESSES_REQUIRED}`:review.status==='uncertain'?' · 不確定，待重溫':' · 答錯，待重溫':'';return `<div class="record-row"><div><div class="record-title">${esc(question.concept)}</div><div class="chapter-meta">第 ${displayPart(question.part)} 部分 · 作答 ${records.length} 次 · 最近：${last.correct?'正確':'錯誤'}${last.uncertain?'／不確定':last.postUncertain?'／作答後標記不確定':''}${reviewState}</div></div><button class="quiet" data-action="review-one" data-id="${esc(question.id)}">再做一次 →</button></div>`}).join(''):'<p class="muted">暫無紀錄。</p>';return `<div class="page-heading"><div><a class="quiet back-link" href="#practice">← 返回題庫</a><h1>錯題與練習紀錄</h1><p class="muted">${esc(recordScope())}</p></div></div><div class="analysis-stats">${statsHTML([[completed.length,'已完成'],[pending.length,'待重溫'],[reviewed.length,'已再次練習']])}</div><section class="record-section"><h2>待重溫</h2><p class="muted">在兩個不同日期答對後，題目會自動移出此清單。</p>${rows(pending)}</section><section class="record-section"><h2>已再次練習</h2>${rows(reviewed)}</section><section class="record-section"><h2>全部已完成</h2>${rows(completed)}</section>`}
const conceptKey=()=>account?`${account.user.id}:${track().id}`:null;
async function loadReviewConcepts({force=false}={}){
 if(!account)return;const key=conceptKey(),epoch=accountEpoch,selectedTrack=track().id,existing=conceptCache.get(key);
 if(existing?.loading&&!force)return existing.promise;
 if(existing?.loaded&&!force)return;
 const entry={items:[],loaded:false,loading:true,error:'',promise:null,accessExpiry:paidActive()?Date.parse(account.entitlement.expiresAt):null};conceptCache.set(key,entry);
 const valid=()=>epoch===accountEpoch&&account&&conceptCache.get(key)===entry;
 entry.promise=(async()=>{try{let after='',more=true,pages=0;const items=new Map();while(more&&pages++<100){const data=await api.request(`/api/review-concepts?track=${selectedTrack}&after=${encodeURIComponent(after)}&limit=50`);if(!valid())return;if(!Array.isArray(data.items)||typeof data.hasMore!=='boolean'||typeof data.cursor!=='string'||data.items.some(item=>typeof item.questionId!=='string'||!Number.isInteger(item.questionVersion)||!Number.isInteger(item.part)||!['concept','core','apply','memory'].every(field=>typeof item[field]==='string')))throw Error('概念資料未能讀取，請重試。');for(const item of data.items)items.set(item.questionId,{questionId:item.questionId,questionVersion:item.questionVersion,part:item.part,concept:item.concept,core:item.core,apply:item.apply,memory:item.memory});more=data.hasMore;if(more&&(!data.cursor||data.cursor===after))throw Error('概念分頁未能繼續，請重試。');after=data.cursor;}if(more)throw Error('概念紀錄較多，請重試。');if(valid()){entry.items=Array.from(items.values());entry.loaded=true;}}
 catch(error){if(valid()){entry.error=errorMessage(error,error?.message||'概念資料未能載入，請重試。');entry.items=[];}}
 finally{if(valid()){entry.loading=false;if(route()==='concepts'&&track().id===selectedTrack)render();}}})();return entry.promise;
}
function cloudConcepts(){
 const entry=conceptCache.get(conceptKey());if(!entry||entry.accessExpiry&&entry.accessExpiry<=Date.now()){void loadReviewConcepts({force:!!entry});return '<section class="empty"><h1>弱項概念</h1><p role="status">正在讀取雲端概念…</p></section>';}
 if(entry.loading)return '<section class="empty"><h1>弱項概念</h1><p role="status">正在讀取雲端概念…</p></section>';
 if(entry.error)return `<section class="empty"><h1>概念未能載入</h1><p class="error-text" role="alert">${esc(entry.error)}</p><button class="secondary" data-action="reload-concepts">重新載入</button></section>`;
 const unique=[],seen=new Set();for(const item of entry.items){const key=`${item.part}:${item.concept}`;if(!seen.has(key)){seen.add(key);unique.push(item);}}
 if(!unique.length){const pending=reviews().filter(([id])=>trackAttempts().some(attempt=>attempt.questionId===id)).length;return `<section class="empty"><h1>${pending?'目前沒有可讀取的概念':'尚未建立弱項'}</h1><p>${pending?'待重溫紀錄仍保留。':'答錯或標記不確定的題目，會在此整理成概念清單。'}</p><a class="secondary" href="#history">查看錯題與紀錄</a><button class="quiet" data-action="reload-concepts">重新整理</button></section>`;}
 return `<div class="page-heading"><div><a class="quiet back-link" href="#practice">← 返回題庫</a><h1>弱項概念</h1><p class="muted">根據此帳戶尚待鞏固的題目整理</p></div><span class="chip">${unique.length} 個概念</span></div><article class="concept-review">${parts.filter(part=>track().parts.includes(part.id)&&unique.some(item=>item.part===part.id)).map(part=>`<details class="concept-group" open><summary class="concept-part"><span>${String(displayPart(part.id)).padStart(2,'0')}</span><h2>${esc(part.title)}</h2></summary>${unique.filter(item=>item.part===part.id).map(item=>`<div class="concept-note"><h3>${esc(item.concept)}</h3><p>${esc(item.core)}</p>${item.apply?`<h4>逐步套用</h4><p>${esc(item.apply)}</p>`:''}${item.memory?`<h4>易錯提示</h4><p>${esc(item.memory)}</p>`:''}<button class="quiet" data-action="review-one" data-id="${esc(item.questionId)}">再做一次 →</button></div>`).join('')}</details>`).join('')}</article>`;
}
function concepts(){if(account)return cloudConcepts();const weakIds=new Set(reviews().map(([id])=>id));const pool=trackQuestions().filter(unlocked).filter(question=>weakIds.has(question.id));if(!pool.length)return `<div class="empty"><span class="empty-symbol">○</span><h1>尚未建立弱項</h1><p>答錯或標記不確定的題目，會在此整理成概念清單。</p><a class="primary" href="#practice">開始練習</a></div>`;const unique=[];const seen=new Set();for(const question of pool){const key=`${question.part}:${question.concept}`;if(!seen.has(key)){seen.add(key);unique.push(question)}}return `<div class="page-heading"><div><a class="quiet back-link" href="#practice">← 返回題庫</a><h1>弱項概念</h1><p class="muted">根據目前尚待鞏固的題目整理</p></div><span class="chip">${unique.length} 個概念</span></div><article class="concept-review">${parts.filter(part=>track().parts.includes(part.id)&&unique.some(question=>question.part===part.id)).map(part=>`<details class="concept-group" open><summary class="concept-part"><span>${String(displayPart(part.id)).padStart(2,'0')}</span><h2>${esc(part.title)}</h2></summary>${unique.filter(question=>question.part===part.id).map(question=>`<div class="concept-note"><h3>${esc(question.concept)}</h3><p>${esc(question.explanation)}</p><button class="quiet" data-action="review-one" data-id="${esc(question.id)}">再做一次 →</button></div>`).join('')}</details>`).join('')}</article>`}

function explanation(question,attempt){const feedback=account?attempt.explanation||state.session?.explanation:null;const answer=account?question.optionIds?.indexOf(feedback?.answerOptionId):question.answer;const content=feedback?.content;const text=typeof content==='string'?content:content?.core||content?.explanation||content?.content||content?.summary||'';const notes=account?content?.options?question.optionIds.map(id=>content.options[id]):content?.optionNotes:question.optionNotes;return `<section class="feedback ${attempt.correct?'':'error'}" aria-labelledby="feedback-title"><h2 id="feedback-title" tabindex="-1">${attempt.correct?'✓ 答案正確':'✕ 答案錯誤'} ${Number.isInteger(answer)&&answer>=0?`<span class="chip">正確答案 ${letter(answer)}</span>`:''}</h2><p class="eyebrow">核心概念</p><h3>${esc(content?.concept||attempt.concept||question.concept)}</h3><p>${esc(account?text||'解說尚未取得，請重新整理。':question.explanation)}</p>${content?.apply||content?.application?`<h3>逐步套用</h3><p>${esc(content.apply||content.application)}</p>`:''}${content?.memory?`<h3>易錯提示</h3><p>${esc(content.memory)}</p>`:''}${notes?.length?`<details><summary>逐項查看選項</summary>${notes.map((note,index)=>`<p><strong>${letter(index)}</strong> · ${esc(typeof note==='string'?note:note.text||note.explanation)}</p>`).join('')}</details>`:''}</section>`}
function quiz(){
 const session=state.session,question=current();if(!session||!question)return '<div class="empty"><h1>尚未開始練習</h1><a class="primary" href="#practice">前往題庫</a></div>';if(!unlocked(question))return paywall('這道題目');const attempt=session.result,pending=!!session.pendingEventId,marked=attempt&&(attempt.uncertain||attempt.postUncertain||state.reviews[question.id]?.status==='uncertain');
 const answer=account?question.optionIds?.indexOf(session.explanation?.answerOptionId):question.answer;
 return `<section class="quiz"><div class="quiz-top"><a class="quiet" href="#practice">← 返回題庫</a><span>${session.index+1} / ${session.ids.length} 題</span></div><div class="quiz-progress"><span style="width:${(session.index+1)/session.ids.length*100}%"></span></div><div class="inline-group"><span class="eyebrow">第 ${displayPart(question.part)} 部分 · ${esc(partMeta(question.part).short)}</span><span class="chip">${esc(question.type||'獨立題')}</span></div>${question.caseStem?`<aside class="case">${esc(question.caseStem)}</aside>`:''}<h1 class="question" id="question-title" tabindex="-1">${esc(question.stem)}</h1><form id="answer-form"><fieldset class="options" aria-labelledby="question-title">${question.options.map((option,index)=>{const correct=attempt&&index===answer,wrong=attempt&&!attempt.correct&&index===attempt.selected;return `<label class="option ${correct?'correct':wrong?'wrong':''}"><input type="radio" name="answer" value="${index}" ${attempt||pending?'disabled':''} ${(attempt?attempt.selected:session.draft?.selected)===index?'checked':''}><span class="letter">${letter(index)}</span><span>${esc(option)}</span></label>`}).join('')}</fieldset><div class="question-actions"><label class="check-label"><input type="checkbox" name="uncertain" ${(attempt?attempt.uncertain:session.draft?.uncertain)?'checked':''} ${attempt||pending?'disabled':''}>仍然不確定</label>${attempt?`<button type="button" class="primary" data-action="next">${session.index===session.ids.length-1?'查看結果':'下一題'} →</button>`:pending?'<button class="secondary" type="button" data-action="sync-now">重試同步</button>':'<button class="primary" type="submit">提交答案</button>'}</div><p id="answer-error" class="error-text" role="alert"></p></form>${pending?`<p class="pending-note" role="status">${esc(outbox.lastError||'答案已保存至此帳戶的待同步佇列；伺服器確認後顯示結果。')}</p>`:''}${attempt?explanation(question,attempt):''}${attempt?`<div class="question-actions post-answer-actions"><button class="secondary" data-action="mark-uncertain" ${marked?'disabled':''}>${marked?'已加入重溫':'仍然不確定，加入重溫'}</button><span class="saved-label">✓ ${account?'伺服器已確認':'已儲存於此瀏覽器'}${attempt.correct&&!marked?'':' · 已加入重溫'}</span></div>`:''}</section>`;
}

function summary(){const finished=state.lastSession;if(!finished)return practice();const sessionAttempts=attempts().filter(attempt=>finished.attemptIds?finished.attemptIds.includes(attempt.id):attempt.id.startsWith(finished.id+':'));return `<section class="quiz"><span class="eyebrow">本輪練習完成</span><h1>${esc(finished.title)}</h1><div class="summary-number">${sessionAttempts.filter(attempt=>attempt.correct).length}<small> / ${sessionAttempts.length} 題正確</small></div><p class="muted">${sessionAttempts.filter(attempt=>!attempt.correct||attempt.uncertain||attempt.postUncertain).length} 題已加入重溫</p><div class="summary-results">${sessionAttempts.map(attempt=>{const question=questions.find(item=>item.id===attempt.questionId);return `<details class="review-row"><summary>${attempt.correct?'✓':'✕'} ${esc(question?.concept)}</summary>${question?explanation(question,attempt):''}</details>`}).join('')}</div><a class="primary" href="#practice">返回題庫</a></section>`}
function analysis(){const all=trackAttempts();const first=firstAttempts({attempts:all});const accuracy=percent(first);const covered=new Set(all.map(attempt=>attempt.questionId)).size;const days=Array.from({length:7},(_,index)=>addDays(dateKey(),index-6));const times=days.map(day=>(state.usage[day]||0)/60);const max=Math.max(25,...times);return `<div class="page-heading"><div><p class="eyebrow">${track().short} · ${track().code}</p><h1>學習進度</h1><p class="muted">${esc(recordScope())}</p></div></div><div class="analysis-stats">${statsHTML([[all.length,'累計作答'],[accuracy===null?'—':accuracy+'%','首次正確率'],[covered+' / '+catalogTotal(),'題庫覆蓋']])}</div><div class="analysis-layout"><section><h2>各部分表現</h2>${parts.filter(part=>track().parts.includes(part.id)).map(part=>{const list=first.filter(attempt=>attempt.part===part.id);const value=percent(list);return `<div class="performance-row"><div class="performance-label"><span>${String(displayPart(part.id)).padStart(2,'0')} ${esc(part.short)}</span><span>${value===null?'未評估':`${value}% · ${list.length} 題`}</span></div><div class="bar"><span style="width:${value||0}%"></span></div></div>`}).join('')}</section><section><h2>最近七日 · 有效學習時間</h2><p><strong style="font-size:36px">${Math.floor((state.usage[dateKey()]||0)/60)}</strong> <span class="muted">分鐘 · 今日</span></p><p class="microcopy">前景使用時間：${Object.hasOwn(state.foregroundUsage||{},dateKey())?Math.floor(state.foregroundUsage[dateKey()]/60)+' 分鐘':'未記錄'} · 背景及兩分鐘無操作不計有效時間。</p><div class="week-chart">${days.map((day,index)=>`<div class="day-column"><span>${Math.floor(times[index])}</span><div class="day-bar" style="height:${times[index]/max*110}px"></div><span>${day.slice(8)}</span></div>`).join('')}</div><div class="weak-link"><h3>集中處理個人錯題</h3><a class="secondary" href="#history">查看待重溫題目 →</a></div></section></div>`}

function passwordField(name='password',label='密碼',autocomplete='current-password'){return `<label class="field">${label}<div class="password-row"><input id="${name}" name="${name}" type="password" autocomplete="${autocomplete}" required minlength="${configuration.passwordMinLength||12}" maxlength="128" ${autocomplete==='new-password'?'aria-describedby="password-hint"':''}><button type="button" class="quiet" data-action="toggle-password" data-target="${name}" aria-label="顯示密碼">顯示</button></div></label>`;}
function authPage(mode){
 const titles={login:'登入帳戶',signup:'建立帳戶',forgot:'重設密碼',reset:'設定新密碼'},enabled=configuration.authEnabled;
 const disabled=!enabled||(mode==='signup'&&(!configuration.termsVersion||!configuration.privacyVersion));
 if(account&&!outbox.paused&&mode!=='reset')return accountPage();
 return `<section class="auth-page"><a class="quiet back-link" href="#practice">← 返回題庫</a><p class="eyebrow">地產牌研所</p><h1>${titles[mode]}</h1><p class="muted">${mode==='login'?'登入後保存作答、錯題及學習進度。':mode==='signup'?'以電郵建立個人學習帳戶。':mode==='forgot'?'輸入電郵以取得密碼重設連結。':'完成後請使用新密碼重新登入。'}</p>${!enabled?'<p class="pending-note" role="status">帳戶服務尚未啟用。你仍可使用訪客試用。</p>':''}<form id="auth-form" data-mode="${mode}">${mode!=='reset'?'<label class="field">電郵<input name="email" type="email" autocomplete="email" inputmode="email" required maxlength="254"></label>':''}${mode!=='forgot'?passwordField('password',mode==='reset'?'新密碼':'密碼',['signup','reset'].includes(mode)?'new-password':'current-password'):''}${['signup','reset'].includes(mode)?`<p id="password-hint" class="microcopy">至少 ${configuration.passwordMinLength||12} 個字元。</p>`:''}${mode==='signup'?'<label class="check-label terms-check"><input type="checkbox" name="terms" required><span>我已閱讀並同意<a class="text-link" href="#terms" target="_blank" rel="noopener">服務條款</a>及<a class="text-link" href="#privacy" target="_blank" rel="noopener">私隱政策</a>。</span></label>':''}<p id="auth-error" class="error-text" role="alert">${esc(authError)}</p><p id="auth-notice" class="auth-notice" role="status">${esc(authNotice)}</p><button class="primary" type="submit" ${disabled||authBusy?'disabled':''}>${authBusy?'處理中…':mode==='login'?'登入':mode==='signup'?'建立帳戶':mode==='forgot'?'寄送重設連結':'更新密碼'}</button></form><div class="auth-links">${mode==='login'?'<a class="text-link" href="#signup">建立帳戶</a><a class="text-link" href="#forgot">忘記密碼</a>':'<a class="text-link" href="#login">返回登入</a>'}</div>${mode==='login'?'<button class="quiet" data-action="resend-verification">重新寄送驗證信</button>':''}</section>`;
}
function accountPage(){if(!account)return authPage('login');const expiry=account.entitlement?.expiresAt;const date=expiry?new Intl.DateTimeFormat('zh-HK',{timeZone:'Asia/Hong_Kong',dateStyle:'long',timeStyle:'short'}).format(new Date(expiry)):'—';return `<section class="account-page"><p class="eyebrow">個人帳戶</p><h1>帳戶與同步</h1><dl class="account-details"><div><dt>電郵</dt><dd>${esc(account.user.email)}</dd></div><div><dt>驗證狀態</dt><dd>${account.user.verified?'已驗證':'尚未驗證'}</dd></div><div><dt>方案</dt><dd>${paidActive()?'考期通行證':'免費帳戶'}</dd></div><div><dt>到期時間</dt><dd>${esc(date)}<small>香港時間</small></dd></div><div><dt>資料同步</dt><dd>${esc(syncLabel())}</dd></div></dl>${syncError||outbox.lastError?`<p class="error-text" role="alert">${esc(syncError||outbox.lastError)}</p>`:''}<div class="inline-group"><button class="primary" data-action="sync-now">重新整理紀錄</button><button class="secondary" data-action="settings">學習設定</button><button class="quiet" data-action="logout">登出</button></div><hr><h2>個人資料</h2><div class="inline-group"><button class="secondary" data-action="export">匯出雲端紀錄</button>${outbox.pending?'<button class="secondary" data-action="export-pending">匯出待同步資料</button>':''}<button class="quiet" data-action="delete-account">刪除帳戶</button></div><p class="microcopy">訪客紀錄不會自動併入帳戶。登出後清除帳戶快取，未同步事件保留在原帳戶。</p></section>`;}
function policyPage(kind){return `<article class="auth-page"><a class="quiet back-link" href="#signup">← 返回註冊</a><h1>${kind==='terms'?'服務條款':'私隱政策'}</h1><p class="pending-note">正式${kind==='terms'?'帳戶服務條款':'私隱政策'}尚未公布。公開註冊須待文案及版本確認後才啟用。</p></article>`;}
function helpPage(){return `<article class="help-page"><a class="quiet back-link" href="#practice">← 返回題庫</a><p class="eyebrow">使用指南</p><h1>開始你的備試練習</h1><ol><li><h2>選擇考試</h2><p>切換大牌 EAQE 或細牌 SQE，並在設定中選擇目標場次。</p></li><li><h2>選擇範圍</h2><p>按考試綱要選擇主題，或開始一輪快速練習。</p></li><li><h2>提交答案</h2><p>選擇答案；若沒有把握，勾選「仍然不確定」。提交前可更改選項。</p></li><li><h2>閱讀固定詳解</h2><p>作答後查看正確答案、核心概念及選項說明。帳戶練習須待伺服器確認後才顯示結果。</p></li><li><h2>重溫錯題</h2><p>答錯或不確定的題目加入「錯題與紀錄」。同一題在兩個不同的香港日期答對，且沒有標記不確定，才完成重溫。</p></li></ol><h2>紀錄保存</h2><p>訪客紀錄只保存在目前瀏覽器。登入後，帳戶作答與進度保存至雲端；訪客紀錄不會自動匯入。離線答案先保留於此帳戶的待同步佇列。</p><h2>目前開放範圍</h2><p>訪客原型內容仍待覆核。帳戶服務須完成設定後才啟用；AI 問答及付款尚未開放。</p><div class="inline-group"><a class="primary" href="#practice">前往題庫</a><a class="secondary" href="#account">帳戶與同步</a></div></article>`;}
function render(){
 const currentRoute=route(),authRoute=['login','signup','forgot','reset'].includes(currentRoute),selected=['practice','quiz','summary','history','concepts'].includes(currentRoute)?'practice':currentRoute.startsWith('part/')?'learning':currentRoute;
 document.querySelectorAll('header nav a').forEach(link=>link.hash==='#'+selected?link.setAttribute('aria-current','page'):link.removeAttribute('aria-current'));const accountLink=document.querySelector('.account-link');if(accountLink){accountLink.href=account?'#account':'#login';accountLink.textContent=account?'帳戶':'登入';}
 const content=authRoute?authPage(currentRoute):currentRoute==='account'?accountPage():['terms','privacy'].includes(currentRoute)?policyPage(currentRoute):currentRoute.startsWith('auth-callback')?'<div class="empty"><h1>正在驗證連結</h1><p role="status">請稍候。</p></div>':currentRoute==='learning'?learning():currentRoute.startsWith('part/')?partPage():currentRoute==='practice'?practice():currentRoute==='history'?history():currentRoute==='concepts'?concepts():currentRoute==='quiz'?quiz():currentRoute==='summary'?summary():currentRoute==='analysis'?analysis():currentRoute==='pricing'?pricing():currentRoute==='help'?helpPage():home();
 main.innerHTML=(authRoute||['terms','privacy'].includes(currentRoute)?'':syncBanner())+(!account&&!authRoute&&!['terms','privacy'].includes(currentRoute)?'<p class="prototype-label">原型內容，待覆核</p>':'')+(!account&&questionLoadError&&!authRoute?`<p class="pending-note" role="alert">${esc(questionLoadError)} <a class="text-link" href="./">重新載入</a></p>`:'')+content;document.title=`${selected==='home'?'主頁':selected==='practice'?'練習題庫':selected==='analysis'?'學習進度':selected==='learning'?'學習範圍':selected==='pricing'?'方案':authRoute?'帳戶':product.name}｜${product.name}`;
}

async function start(pool,title,mode='practice'){if(!account&&questionLoadError){toast(questionLoadError,true);return}if(account){if(cloudBusy){toast('請等待目前同步完成。');return}try{const body={eventId:crypto.randomUUID(),track:track().id,mode:mode==='review'?'review':'practice',count:Math.min(pool.length||10,50)};if(pool.length)body.questionIds=randomSample(pool,Math.min(pool.length,50)).map(q=>q.id);const data=await api.request('/api/practice-sessions',{method:'POST',body});mergeSession(data.session);saveDraft();go('quiz');}catch(error){toast(errorMessage(error,error.code==='no_questions'||error.status===422?'雲端題目尚未備妥。':undefined),true);}return}const accessible=pool.filter(unlocked);if(!accessible.length){go('pricing');return}if(state.session&&current()){dialog.innerHTML='<div class="dialog-head"><h2>開始另一輪練習？</h2></div><p>已提交的答案會保留，目前未完成的練習將會結束。</p><div class="inline-group"><button class="primary" id="confirm-start">開始</button><button class="secondary" data-action="close-dialog">取消</button></div>';dialog.showModal();const confirmed=await new Promise(resolve=>{dialog.querySelector('#confirm-start').onclick=()=>{resolve(true);dialog.close()};dialog.addEventListener('close',()=>resolve(false),{once:true})});if(!confirmed)return}const selected=accessible.length>10&&mode!=='part-all'?randomSample(accessible,10):accessible;const ok=await mutate(next=>{next.session={id:crypto.randomUUID(),title,mode,ids:selected.map(question=>question.id),index:0,result:null,draft:{},activeMs:0}});if(ok)go('quiz')}
function settings(selectedTrack=track().id){const selectedDate=exams.find(exam=>exam.date===state.settings.examDate&&exam.date>=dateKey())?.track===selectedTrack?state.settings.examDate:'';dialog.innerHTML=`<div class="dialog-head"><h2 id="settings-title">設定</h2><button class="quiet" data-action="close-dialog">✕</button></div><form id="settings-form"><label class="field">考試類別<select name="track"><option value="eaqe" ${selectedTrack==='eaqe'?'selected':''}>大牌 · 地產代理資格考試</option><option value="sqe" ${selectedTrack==='sqe'?'selected':''}>細牌 · 營業員資格考試</option></select></label>${examSelect(selectedTrack,selectedDate)}<button class="primary" type="submit">儲存設定</button></form><hr><h3>學習紀錄</h3><p class="muted">${account?'已確認的作答與進度保存至雲端。清除此裝置資料不會刪除雲端帳戶。':'訪客紀錄只儲存在此瀏覽器。'}</p><div class="inline-group"><button class="secondary" data-action="export">匯出我的紀錄</button><button class="quiet" data-action="clear-records">清除本機紀錄</button></div><p class="source-note"><a class="text-link" href="${scheduleUrl}" target="_blank" rel="noopener noreferrer">官方考試時間表 ↗</a> · 核實 ${verifiedAt}</p>`;if(!dialog.open)dialog.showModal()}

async function saveCloudSettings(settingsValue){const response=await api.request('/api/settings',{method:'PUT',body:{expectedVersion:settingsVersion,settings:settingsValue}});state.settings={...state.settings,...(response.settings||settingsValue)};settingsVersion=response.settingsVersion??response.version??settingsVersion+1;account.settings=state.settings;account.settingsVersion=settingsVersion;render();}
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function performLogout(){try{await api.request('/api/auth/logout',{method:'POST',body:{}});setGuest();try{localStorage.setItem('propexam-auth-change',crypto.randomUUID());}catch{}dialog.close();go('login');toast('已登出。');}catch(error){toast('登出未完成：'+errorMessage(error),true);}}
async function authCallback(){if(!initialCallback&&!route().startsWith('auth-callback'))return;const params=new URLSearchParams(route().split('?')[1]||'');const {tokenHash,type}=initialCallback||{tokenHash:params.get('token_hash'),type:params.get('type')};initialCallback=null;window.history.replaceState(null,'',location.pathname+location.search+'#login');authNotice='';authError='';render();if(!tokenHash||!['signup','recovery'].includes(type)){authError='驗證連結無效或已過期。';render();return}try{const result=await api.request('/api/auth/callback',{method:'POST',body:{tokenHash,type}});if(type==='recovery'&&result.recoveryReady){go('reset');authNotice='連結已確認，請設定新密碼。';}else{authNotice=result.message||'電郵已驗證，請登入。';go('login');}}catch(error){authError=errorMessage(error);}render();}

document.addEventListener('click',async event=>{const loginLink=event.target.closest('a[href="#login"]');if(loginLink)returnTo=safeReturnRoute(route());const authLink=event.target.closest('a[href="#login"],a[href="#signup"],a[href="#forgot"],a[href="#reset"]');if(authLink){authError='';authNotice='';}const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
 if(action==='toggle-password'){const input=document.getElementById(button.dataset.target);if(input){input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'顯示':'隱藏';button.setAttribute('aria-label',input.type==='password'?'顯示密碼':'隱藏密碼');}return;}
 if(action==='sync-now'){await syncCloud({refreshAccount:true,manual:true});return;}
 if(action==='reload-concepts'){await loadReviewConcepts({force:true});return;}
 if(action==='export-pending'){downloadJSON(outbox.export(),`propexam-pending-${dateKey()}.json`);return;}
 if(action==='resend-verification'){const email=document.querySelector('#auth-form [name="email"]')?.value;if(!email||!document.querySelector('#auth-form [name="email"]').checkValidity()){toast('請先輸入有效電郵。');return}try{const data=await api.request('/api/auth/resend',{method:'POST',body:{email}});authNotice=data.message;authError='';render();}catch(error){authError=errorMessage(error);render();}return;}
 if(action==='logout'){if(outbox.pending){dialog.innerHTML='<div class="dialog-head"><h2>尚有待同步資料</h2><button class="quiet" data-action="close-dialog">✕</button></div><p>待同步資料只屬於目前帳戶，下一位登入者無法讀取。你可以先同步、匯出，或保留資料後登出。</p><div class="inline-group"><button class="primary" data-action="sync-logout">同步後登出</button><button class="secondary" data-action="export-pending">匯出待同步資料</button><button class="quiet" data-action="confirm-logout">保留資料並登出</button></div>';dialog.showModal();}else await performLogout();return;}
 if(action==='sync-logout'){await syncCloud({manual:true});if(!outbox.pending)await performLogout();else toast('尚有資料未同步。請匯出或選擇保留資料並登出。',true);return;}
 if(action==='confirm-logout'){await performLogout();return;}
 if(action==='delete-account'){dialog.innerHTML=`<div class="dialog-head"><h2>刪除雲端帳戶</h2><button class="quiet" data-action="close-dialog">✕</button></div><p>此操作會刪除帳戶及學習紀錄，不能復原。請先匯出所需資料。有效通行證或須保留的付款紀錄可能需要另行處理。</p><form id="delete-account-form">${passwordField('delete-password','重新輸入密碼')}<label class="field">輸入 DELETE 確認<input name="confirmation" autocomplete="off" required pattern="DELETE"></label><p class="error-text" id="delete-error" role="alert"></p><button class="primary" type="submit">確認刪除帳戶</button></form>`;dialog.showModal();return;}
 if(action==='settings')settings();
 if(action==='close-dialog')dialog.close();
 if(action==='set-track'&&account){try{const selectedTrack=button.dataset.track;await saveCloudSettings({track:selectedTrack,examDate:''});}catch(error){toast(errorMessage(error,error.status===409?'設定已在另一部裝置更新。請重新整理後再試。':undefined),true);}return}
 if(action==='set-track'){await mutate(next=>{next.settings.track=button.dataset.track;const selected=exams.find(exam=>exam.date===next.settings.examDate);if(selected?.track!==next.settings.track)next.settings.examDate='';next.session=null});toast(`已切換至${track().name}。`)}
 if(action==='home-start'){if(state.session&&current())go('quiz');else await start(nextPool(),'快速練習')}
 if(action==='start-next')await start(nextPool(),'快速練習');
 if(action==='start-part'&&account){try{const data=await api.request('/api/practice-sessions',{method:'POST',body:{eventId:crypto.randomUUID(),track:track().id,mode:'practice',part:Number(button.dataset.part),count:10}});mergeSession(data.session);saveDraft();go('quiz');}catch(error){toast(errorMessage(error),true);}return}
 if(action==='start-part'){const id=Number(button.dataset.part);await start(trackQuestions().filter(question=>question.part===id),`第 ${displayPart(id)} 部分練習`)}
 if(action==='review-due'&&account){const ids=due().map(([id])=>({id}));await start(ids,'到期錯題重溫','review');return}
 if(action==='review-due'){const ids=new Set(due().map(([id])=>id));await start(trackQuestions().filter(question=>ids.has(question.id)),'到期錯題重溫','review')}
 if(action==='review-one'&&account){await start([{id:button.dataset.id}],'題目重溫',state.reviews[button.dataset.id]&&state.reviews[button.dataset.id].status!=='completed'?'review':'practice');return}
 if(action==='review-one'){const question=questions.find(item=>item.id===button.dataset.id);if(question)await start([question],`重溫：${question.concept}`,'review')}
 if(action==='next'&&account){if(!state.session?.result||busy)return;busy=true;try{const old=state.session;const data=await api.request('/api/practice-sessions',{method:'PATCH',body:{sessionId:old.id,expectedVersion:old.serverVersion}});if(data.session.status==='completed'){state.lastSession={id:old.id,title:old.title,attemptIds:state.attempts.filter(a=>a.sessionId===old.id||a.id===old.result.id).map(a=>a.id)};state.session=null;cloudSession=null;saveDraft();go('summary');}else{mergeSession(data.session);saveDraft();render();window.scrollTo({top:0});document.querySelector('#question-title')?.focus();}}catch(error){toast(errorMessage(error,error.status===409?'練習進度已更新，請重新整理。':undefined),true);}finally{busy=false;}return}
 if(action==='next'){const completed=state.session?.index===state.session?.ids.length-1;const ok=await mutate(next=>{if(!next.session?.result)return;if(completed){next.lastSession={id:next.session.id,title:next.session.title};next.session=null}else{next.session.index+=1;next.session.result=null;next.session.draft={};next.session.activeMs=0}});if(ok){if(completed)go('summary');else{render();window.scrollTo({top:0});document.querySelector('#question-title')?.focus()}}}
 if(action==='mark-uncertain'&&account){const result=state.session?.result;if(result&&!result.uncertain){try{await outbox.enqueueDurably('review',{eventId:crypto.randomUUID(),attemptId:result.id});await flushOutbox(true);if(outbox.pending)toast('已保存待同步重溫標記。');else toast('已加入重溫。');}catch(error){toast(errorMessage(error),true);}}return}
 if(action==='mark-uncertain'){const question=current();const result=state.session?.result;if(question&&result){await mutate(next=>{const saved=next.attempts.find(attempt=>attempt.id===result.id);if(saved)saved.uncertain=true;if(next.session?.result)next.session.result.uncertain=true;next.reviews[question.id]={status:'uncertain',due:addDays(dateKey(),1),lastAt:Date.now(),successes:0}});toast('已加入翌日重溫。')}}
 if(action==='buy'){dialog.innerHTML=`<div class="dialog-head"><h2>首批試行方案</h2><button class="quiet" data-action="close-dialog">✕</button></div><p>每場考試獨立購買：考前 ${product.preExamDays} 日開始，考試結束後 ${product.postExamDays} 日到期；未合格後報考下一場須重新購買。安全付款及帳戶系統仍在接入，現時不會收取款項。</p><a class="secondary" href="#practice" data-action="close-dialog">先使用免費題目</a>`;dialog.showModal()}
 if(action==='export'&&account){try{const data=await api.request('/api/export');downloadJSON(data,`propexam-account-${dateKey()}.json`);}catch(error){toast(errorMessage(error),true);}return}
 if(action==='export'){const raw=localStorage.getItem(KEY)||JSON.stringify(state);const url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`propexam-records-${dateKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 if(action==='clear-records'){dialog.innerHTML=`<div class="dialog-head"><h2>清除本機紀錄？</h2><button class="quiet" data-action="close-dialog">✕</button></div><p>${account?'此操作只清除此帳戶在本裝置的未同步事件及作答草稿；已同步的雲端紀錄保留。未同步資料將無法復原。':'此操作會刪除這個瀏覽器內的作答、錯題及進度紀錄。'}</p><div class="inline-group"><button class="primary" data-action="confirm-clear">確認清除</button><button class="secondary" data-action="close-dialog">取消</button></div>`;dialog.showModal()}
 if(action==='confirm-clear'&&account){try{outbox.clear();localStorage.removeItem(draftKey(account.user.id));dialog.close();await syncCloud({refreshAccount:true});toast('此裝置的待同步資料已清除；雲端紀錄保留。');}catch(error){toast(errorMessage(error),true);}return}
 if(action==='confirm-clear'){localStorage.removeItem(KEY);storageProblem='';state=initial();dialog.close();render();toast('本機學習紀錄已清除。')}
});
document.addEventListener('submit',async event=>{const form=event.target;if(!['onboarding','settings-form','answer-form','auth-form','delete-account-form'].includes(form.id))return;event.preventDefault();const data=new FormData(form);
 if(form.id==='auth-form'){
  if(authBusy)return;const mode=form.dataset.mode;if(!configuration.authEnabled){toast('帳戶服務尚未啟用。');return}authBusy=true;authError='';authNotice='';const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='處理中…';
  try{const body=mode==='reset'?{password:String(data.get('password')||'')}:{email:String(data.get('email')||'').trim()};if(mode==='login'||mode==='signup')body.password=String(data.get('password')||'');if(mode==='signup'){body.acceptedTerms=data.get('terms')==='on';body.termsVersion=configuration.termsVersion;body.privacyVersion=configuration.privacyVersion;}const response=await api.request(`/api/auth/${mode}`,{method:'POST',body});
   if(mode==='login'){const value=await api.request('/api/account');setAccount(value);try{localStorage.setItem('propexam-auth-change',crypto.randomUUID());}catch{}await syncCloud();go(safeReturnRoute(returnTo));}
   else{authNotice=response.message||'如果電郵適用，你將收到下一步指示。';if(mode==='reset'){if(response.sessionsRevoked===false)authNotice+=' 其他裝置的登入狀態尚未全部撤銷。請重新登入後檢查帳戶安全。';setGuest();go('login');}}
  }catch(error){authError=errorMessage(error);}finally{authBusy=false;render();}return;
 }
 if(form.id==='delete-account-form'){
  if(authBusy)return;authBusy=true;form.querySelector('[type=submit]').disabled=true;try{await api.request('/api/account',{method:'DELETE',body:{password:String(data.get('delete-password')||''),confirmation:String(data.get('confirmation')||'')}});outbox.clear();setGuest();dialog.close();go('login');toast('帳戶已刪除。');}catch(error){form.querySelector('#delete-error').textContent=errorMessage(error);form.querySelector('[type=submit]').disabled=false;}finally{authBusy=false;}return;
 }
 if(form.id==='onboarding'||form.id==='settings-form'){
  const selectedTrack=String(data.get('track')||track().id);let examDate=String(data.get('examDate')||'');if(exams.find(exam=>exam.date===examDate)?.track!==selectedTrack)examDate='';if(examDate&&!selectableExams(dateKey(),state.settings.examDate,selectedTrack).some(exam=>exam.date===examDate)){toast('請選擇已公布的考試場次。');return}
  if(account){try{await saveCloudSettings({track:selectedTrack,examDate});if(dialog.open)dialog.close();toast('設定已同步。');}catch(error){toast(errorMessage(error,error.status===409?'另一部裝置已有較新設定。請重新整理後再套用。':undefined),true);}return}
  await mutate(next=>{if(next.settings.track!==selectedTrack)next.session=null;next.settings.track=selectedTrack;next.settings.examDate=examDate});if(dialog.open)dialog.close();toast('設定已儲存。');
 }
 if(form.id==='answer-form'){
  if(busy)return;const choice=data.get('answer');if(choice===null){document.querySelector('#answer-error').textContent='請先選擇答案。';return}busy=true;
  try{const question=current();if(account){if(state.session.pendingEventId)return;const event=await outbox.enqueueDurably('attempt',{eventId:crypto.randomUUID(),sessionId:state.session.id,sessionVersion:state.session.serverVersion,questionId:question.id,questionVersion:question.version,optionId:question.optionIds[Number(choice)],uncertain:data.get('uncertain')==='on',seconds:Math.min(10800,Math.round((state.session.activeMs||0)/1000)),clientOccurredAt:new Date().toISOString()});state.session.pendingEventId=event.id;saveDraft();render();await flushOutbox(true);if(state.session?.result)document.querySelector('#feedback-title')?.focus({preventScroll:true});return}
   const ok=await mutate(next=>submitAnswer(next,question,Number(choice),data.get('uncertain')==='on'));if(ok)document.querySelector('#feedback-title')?.focus({preventScroll:true});
  }catch(error){toast(errorMessage(error),true);}finally{busy=false;}
 }
});
document.addEventListener('change',event=>{if(event.target.matches('#settings-form [name="track"]')){settings(event.target.value);return}if(event.target.closest('#answer-form')&&state.session&&!state.session.result){const data=new FormData(document.querySelector('#answer-form'));mutate(next=>{if(next.session&&!next.session.result)next.session.draft={selected:data.get('answer')===null?null:Number(data.get('answer')),uncertain:data.get('uncertain')==='on'}},false)}});
