['pointerdown','keydown','scroll'].forEach(name=>document.addEventListener(name,()=>lastAction=Date.now(),{passive:true}));
setInterval(()=>{const now=Date.now(),delta=Math.max(0,Math.min(5000,now-lastTick));lastTick=now;if(document.hidden)return;const studyRoute=['quiz','learning','practice','history','concepts','summary'].includes(route())||route().startsWith('part/');const effective=studyRoute&&now-lastAction<=120000;
 mutate(next=>{if(!account){next.foregroundUsage??={};next.foregroundUsage[dateKey(now)]=(next.foregroundUsage[dateKey(now)]||0)+delta/1000;if(effective)next.usage[dateKey(now)]=(next.usage[dateKey(now)]||0)+delta/1000;}if(effective&&route()==='quiz'&&next.session&&!next.session.result&&!next.session.pendingEventId)next.session.activeMs+=delta;},false);
 if(account&&delta){for(const kind of effective?['foreground','effective']:['foreground'])usageSegments.push({id:crypto.randomUUID(),startAt:new Date(now-delta).toISOString(),endAt:new Date(now).toISOString(),kind});}
},5000);
setInterval(async()=>{if(!account)return;try{if(usageSegments.length){await outbox.enqueueDurably('usage',{eventId:crypto.randomUUID(),deviceId,segments:usageSegments.slice(0,100)});usageSegments=usageSegments.slice(100);}await flushOutbox();}catch(error){syncError=errorMessage(error);}},30000);
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();if(!document.hidden&&account)syncCloud({refreshAccount:true});});
