try{const [response,reviewResponse]=await Promise.all([fetch('./questions.json'),fetch('./content-review.json',{cache:'no-store'})]);if(!response.ok)throw Error('題庫載入失敗。');if(!reviewResponse.ok)throw Error('題目覆核清單未能載入，練習暫停。');const [raw,review]=await Promise.all([response.json(),reviewResponse.json()]);if(!Array.isArray(review.blockedQuestionIds)||review.blockedQuestionIds.some(id=>typeof id!=='string')||!/^\d{4}-\d{2}-\d{2}$/.test(review.reviewDate||'')||typeof review.commercialApprovedCount!=='number')throw Error('題目覆核清單不完整，練習暫停。');if(!Array.isArray(raw)||raw.some(question=>!playable(question)||!Array.isArray(question.examTracks)||typeof question.free!=='boolean'||question.optionNotes?.length!==5))throw Error('題庫資料不完整。');const blocked=new Set(review.blockedQuestionIds);questions=raw.filter(question=>!blocked.has(question.id));guestQuestions=questions;if(!questions.length)throw Error('題庫尚未準備完成。');await mutate(next=>{const ids=new Set(questions.filter(question=>question.free).map(question=>question.id));if(next.session&&!next.session.ids.every(id=>ids.has(id)))next.session=null},false);render()}catch(error){questionLoadError=errorMessage(error);main.innerHTML=`<div class="empty"><h1>未能載入題庫</h1><p>${esc(errorMessage(error))}</p><a class="secondary" href="./">重新載入</a></div>`}
